# Check what's already available in the shared runtime
print("Variables already staged:")
for var_name in ['station_data', 'pairwise_df', 'under_5km', 'over_15km', 'avg_diff_under_5km_result', 'avg_diff_over_15km_result', 'distances', 'pm25_diffs']:
    try:
        val = locals().get(var_name, globals().get(var_name, None))
        if val is not None:
            if hasattr(val, 'shape'):
                print(f"  {var_name}: DataFrame with shape {val.shape}")
            elif hasattr(val, '__len__') and not isinstance(val, (str, bytes)):
                print(f"  {var_name}: {type(val).__name__} with length {len(val)}")
            else:
                print(f"  {var_name}: {type(val).__name__} = {val}")
        else:
            print(f"  {var_name}: NOT FOUND")
    except Exception as e:
        print(f"  {var_name}: ERROR - {e}")
